from pathlib import Path
import tempfile, json, base64
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
FIXTURE='''<!doctype html><html><body><main><h1>Appointments</h1><div role="tablist"><button id="tab-day" role="tab" aria-selected="true">Day</button><button id="tab-week" role="tab" aria-selected="false">Week</button><button id="tab-delete" role="tab" aria-selected="false">Delete appointment</button></div><p id="indicator">Day view</p><table id="appts"><thead><tr><th>Service</th></tr></thead><tbody><tr><td>Gel</td></tr><tr><td>Pedi</td></tr><tr hidden><td>Hidden</td></tr></tbody></table></main><script>window.unsafe=0;document.querySelector('#tab-delete').onclick=()=>window.unsafe++;for(const b of document.querySelectorAll('#tab-day,#tab-week'))b.onclick=()=>{for(const x of document.querySelectorAll('[role=tab]'))x.setAttribute('aria-selected',x===b?'true':'false');document.querySelector('#indicator').textContent=b.textContent+' view'};</script></body></html>'''
MOCK='''window._qaStore={suites:[],runs:[]};window.chrome=window.chrome||{};chrome.runtime={sendMessage:async m=>{const Q=window.N360QA,d=window._qaStore;if(m.type==='qa:list')return {ok:true,data:structuredClone(d)};if(m.type==='qa:saveSuite')d.suites=Q.upsert(d.suites,Q.suite(m.suite),40);else if(m.type==='qa:saveRun')d.runs=Q.upsert(d.runs,Q.run(m.run),100);else if(m.type==='qa:issue')d.runs.find(r=>r.id===m.runId).results.find(t=>t.id===m.testId).issue=m.status;else if(m.type==='qa:deleteSuite')d.suites=d.suites.filter(s=>s.id!==m.id);else if(m.type==='qa:clearRuns')d.runs=[];return {ok:true,data:structuredClone(d)};}};chrome.storage={onChanged:{addListener(){}}};const shadow=Element.prototype.attachShadow;Element.prototype.attachShadow=function(opts){return shadow.call(this,{...opts,mode:'open'});};'''
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
