    page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('dialog',lambda d:d.accept())
    page.set_content(FIXTURE)
    # Browser sandbox blocks navigations. Only in this fixture, substitute origin/route and mock the Chrome bridge.
    page.evaluate("()=>{"+MOCK+"}");page.add_script_tag(content=(ROOT/'qa-core.js').read_text());page.evaluate("window.N360QA.ORIGIN=location.origin; if(!crypto.randomUUID) crypto.randomUUID=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('')");page.add_script_tag(content=(ROOT/'support-view.js').read_text());page.add_script_tag(content=(ROOT/'qa-page.js').read_text().replace('location.pathname',"'/fixture'"));page.evaluate('window.__n360QAStudio.show()')
    overlay=page.locator('[data-n360-qa-studio]');overlay.get_by_text('Tùy chọn nâng cao',exact=True).click();overlay.get_by_role('button',name='Kiểm tra kỹ thuật cơ bản').click();page.wait_for_function('window._qaStore.runs.length===1')
    assert page.evaluate('window._qaStore.runs[0].summary')=={'pass':5,'fail':0,'skip':0,'total':5}
    overlay.locator('#name').fill('Appointment regression fixture');overlay.locator('#record').click();page.locator('#tab-week').click();assert page.locator('#indicator').inner_text()=='Week view'
    # Real user clicks a disallowed tab in the fixture; the recorder must not save it.
    page.locator('#tab-delete').click();assert page.evaluate('window.unsafe')==1
    assert '1/40' in overlay.locator('#record-state').inner_text()
    overlay.locator('#expected').fill('Week view');overlay.locator('#text').click();box=page.locator('#indicator').bounding_box();page.mouse.click(box['x']+5,box['y']+5)
    overlay.locator('#expected').fill('2');overlay.locator('#count').click();box=page.locator('#appts td').first.bounding_box();page.mouse.click(box['x']+5,box['y']+5)
    assert '3/40' in overlay.locator('#record-state').inner_text();overlay.locator('#save').click();page.wait_for_function('window._qaStore.suites.length===1');overlay.locator('#suite').select_option(index=1)
    page.locator('#tab-day').click();overlay.locator('#run').click();page.wait_for_function('window._qaStore.runs.length===2');assert page.evaluate('window._qaStore.runs[0].summary.pass')==3;assert page.locator('#indicator').inner_text()=='Week view';assert page.evaluate('window.unsafe')==1
    # Regression after a changed fixture row; actual mismatch is captured.
    page.locator('#appts tbody').evaluate("e=>e.insertAdjacentHTML('beforeend','<tr><td>Extra</td></tr>')");overlay.locator('#run').click();page.wait_for_function('window._qaStore.runs.length===3',timeout=10000);assert page.evaluate('window._qaStore.runs[0].summary.fail')==1;assert page.evaluate('window._qaStore.runs[0].results[2].actual')=='Rendered row count = 3'
    page.screenshot(path=str(ROOT/'studio-preview.png'))
    overlay.locator('#close').click();assert not overlay.is_visible();page.evaluate('window.__n360QAStudio.show()');assert overlay.is_visible()
    data=page.evaluate('window._qaStore');admin=ctx.new_page();admin.on('pageerror',lambda e:errors.append(str(e)));admin.on('dialog',lambda d:d.accept());admin.set_content((ROOT/'admin.html').read_text().replace('<script src="qa-core.js" defer></script>','').replace('<script src="admin.js" defer></script>','').replace('<link rel="stylesheet" href="admin.css">','').replace('icons/logo.svg','data:image/svg+xml;base64,'+base64.b64encode((ROOT/'icons/logo.svg').read_bytes()).decode()));admin.add_style_tag(content=(ROOT/'admin.css').read_text());admin.evaluate("()=>{"+MOCK+"}");admin.evaluate('(data)=>window._qaStore=data',data);admin.add_script_tag(content=(ROOT/'qa-core.js').read_text());admin.add_script_tag(content=(ROOT/'support-view.js').read_text());admin.add_script_tag(content=(ROOT/'module-catalog.js').read_text());admin.add_script_tag(content=(ROOT/'admin.js').read_text());admin.wait_for_function('document.querySelector("#runs").textContent==="3"');assert admin.locator('#pass').inner_text()=='10';assert admin.locator('#fail').inner_text()=='1';assert admin.locator('#open').inner_text()=='1'
    admin.get_by_role('button',name='Quản lý lỗi').click();assert admin.locator('#issues-body .issue').count()==1;admin.locator('#issues-body select').select_option('Investigating');admin.wait_for_function('window._qaStore.runs[0].results[2].issue==="Investigating"');admin.screenshot(path=str(ROOT/'admin-preview.png'));admin.locator('#issues-body select').select_option('Resolved');admin.wait_for_function('document.querySelector("#open").textContent==="0"');assert admin.locator('#issues-body .issue').count()==0
    admin.get_by_role('button',name='Lịch sử chạy').click();admin.locator('#run-filter').select_option('fail');assert admin.locator('#history-body tr').count()==1;admin.locator('#history-body button').click();assert 'Rendered row count = 3' in admin.locator('#run-detail').inner_text()
    with admin.expect_download() as d:admin.locator('#csv').click()
    assert 'Rendered row count = 3' in Path(d.value.path()).read_text(encoding='utf-8-sig');assert not errors,errors
    print('PASS: fixture smoke, real tab recording, unsafe tab exclusion, expected text and visible row assertions, replay PASS/FAIL, panel close/reopen, Admin totals, issue triage, filters, detail, CSV export (mocked storage).')
    ctx.close();browser.close()
